{
  "name": "电压表校准系统",
  "name_en": "Voltage Meter Calibration System",
  "manufacturer": "",
  "description": "用于实验室中对待测设备电压测量通道进行校准与核查的校准系统。该系统通常配合可编程电源、数字万用表和待校准设备使用，通过多个校准点与检查点完成电压表或模数转换读数的校准、平均测量和结果验证。",
  "description_en": "A laboratory calibration system used to calibrate and verify the voltage measurement channel of a device under test. It is typically used together with a programmable power supply, a digital multimeter, and the DUT, applying multiple calibration and check points to calibrate a voltage meter or ADC-based reading, perform averaged measurements, and verify the result.",
  "tag_hints": [
    "voltage calibration",
    "digital multimeter",
    "programmable power supply",
    "measurement verification",
    "ADC measurement",
    "calibration points"
  ],
  "actions": [
    {
      "action_name": "auto-connect_psu",
      "description": "连接用于提供校准电压的电源。",
      "description_en": "Connect the power supply used to provide the calibration voltage."
    },
    {
      "action_name": "auto-connect_dmm",
      "description": "连接作为参考测量仪表的数字万用表。",
      "description_en": "Connect the digital multimeter used as the reference measurement instrument."
    },
    {
      "action_name": "auto-connect_dut",
      "description": "连接待校准的设备。",
      "description_en": "Connect the device under test to be calibrated."
    },
    {
      "action_name": "auto-get_lin_cal_points",
      "description": "获取用于线性校准的电压校准点。",
      "description_en": "Get the voltage calibration points used for linear calibration."
    },
    {
      "action_name": "auto-calibrate_voltage_meter",
      "description": "按照设定的校准点执行电压表校准。",
      "description_en": "Perform voltage meter calibration using the defined calibration points."
    },
    {
      "action_name": "auto-get_cal_check_points",
      "description": "获取用于校准核查的检查点。",
      "description_en": "Get the check points used for calibration verification."
    },
    {
      "action_name": "auto-check_voltage_calibration",
      "description": "检查电压校准后的测量结果是否符合预期。",
      "description_en": "Check whether the voltage measurement after calibration matches the expected result."
    },
    {
      "action_name": "auto-measure_average",
      "description": "进行多次测量并计算平均值，可选用模数转换读数。",
      "description_en": "Perform repeated measurements and calculate an average value, optionally using ADC readings."
    }
  ]
}

